#include <bits/stdc++.h>
using namespace std;

int n;
vector<long long> bit;  // Fenwick tree over original positions: values of cards still present

long long prefix(int i) {
    long long v = 0;
    for (; i; i -= i & -i) v += bit[i];
    return v;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    vector<int> position(n + 1);
    bit.assign(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        int a;
        cin >> a;
        position[a] = i;
        bit[i] += a;
        int parent = i + (i & -i);
        if (parent <= n) bit[parent] += bit[i];
    }
    long long total = (long long)n * (n + 1) / 2, answer = 0;
    int head = 1;
    for (int target = 1; target <= n; target++) {
        int p = position[target];
        // left: cost of rotating front cards to the back until target is in front (circular range).
        long long left = prefix(p - 1) - prefix(head - 1);
        if (p < head) left += total;
        long long right = total - left;  // rotating from the back, target included
        answer += min(left, right);
        for (int i = p; i <= n; i += i & -i) bit[i] -= target;
        total -= target;
        head = p + 1 > n ? 1 : p + 1;
    }
    cout << answer % 1000000007 << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static int n;
    static long[] bit; // Fenwick tree over original positions: values of cards still present

    static long prefix(int i) {
        long v = 0;
        for (; i > 0; i -= i & -i) v += bit[i];
        return v;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        int[] position = new int[n + 1];
        bit = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            int a = nextInt();
            position[a] = i;
            bit[i] += a;
            int parent = i + (i & -i);
            if (parent <= n) bit[parent] += bit[i];
        }
        long total = (long) n * (n + 1) / 2, answer = 0;
        int head = 1;
        for (int target = 1; target <= n; target++) {
            int p = position[target];
            // left: cost of rotating front cards to the back until target is in front (circular range).
            long left = prefix(p - 1) - prefix(head - 1);
            if (p < head) left += total;
            long right = total - left; // rotating from the back, target included
            answer += Math.min(left, right);
            for (int i = p; i <= n; i += i & -i) bit[i] -= target;
            total -= target;
            head = p + 1 > n ? 1 : p + 1;
        }
        System.out.println(answer % 1000000007L);
    }
}

