var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	position := make([]int, n+1)
	bit := make([]int64, n+1) // Fenwick tree over original positions: values of cards still present
	for i := 1; i <= n; i++ {
		a := nextInt()
		position[a] = i
		bit[i] += a
		if parent := i + (i & -i); parent <= n {
			bit[parent] += bit[i]
		}
	}
	prefix := func(i int) int64 {
		var v int64
		for ; i > 0; i -= i & -i {
			v += bit[i]
		}
		return v
	}
	total, answer := int64(n)*int64(n+1)/2, int64(0)
	head := 1
	for target := 1; target <= n; target++ {
		p := position[target]
		// left: cost of rotating front cards to the back until target is in front (circular range).
		left := prefix(p-1) - prefix(head-1)
		if p < head {
			left += total
		}
		right := total - left // rotating from the back, target included
		answer += min(left, right)
		for i := p; i <= n; i += i & -i {
			bit[i] -= int64(target)
		}
		total -= int64(target)
		head = p + 1
		if head > n {
			head = 1
		}
	}
	fmt.Println(answer % 1000000007)
